from __future__ import annotations

import base64
import gzip
import json
import os
import shutil
import subprocess
import sys
import traceback
import unicodedata
from datetime import datetime
from pathlib import Path

PROJECT = Path(os.environ.get("PHOCAP_PROJECT", r"C:\PhoCap")).resolve()
if str(PROJECT) not in sys.path:
    sys.path.insert(0, str(PROJECT))
APP = PROJECT / "app"
DB_PATH = PROJECT / "data" / "phocap.db"

STAMP = datetime.now().strftime("%Y%m%d_%H%M%S")
BACKUP = PROJECT / "exports" / f"backup_bai_13b_6_v1_2_data_{STAMP}"
MANIFEST = BACKUP / "manifest.json"

PAYLOAD = {'app/report_input_models.py': '', 'app/routers/report_inputs.py': '', 'app/pcgd_xmc_report_builders_v1.py': '', 'app/templates/report_inputs/structured_school_form.html': ''}
NETWORK_DATA_B64 = ''

FILES_TO_BACKUP = list(PAYLOAD.keys()) + ["data/phocap.db"]


def _read_text(rel: str) -> str:
    path = PROJECT / rel
    if not path.exists():
        raise RuntimeError(f"Không tìm thấy: {path}")
    return path.read_text(encoding="utf-8-sig")


def _verify_base() -> None:
    # Người dùng chưa chạy V1.2 cũ; bộ cài này yêu cầu nền V1.1 đang chạy.
    required = {
        "app/routers/report_inputs.py": [
            "BAI_13B_6_V1_STRUCTURED_INPUT_START",
        ],
        "app/templates/report_inputs/structured_school_form.html": [
            "BAI_13B_6_V1_1_SAFE_SCOPE_SUBMIT",
        ],
        "app/templates/report_inputs/gv_mn01.html": [
            "BAI_13B_6_V1_1_SAFE_SCOPE_SUBMIT",
        ],
        "app/templates/report_inputs/csvc_mn01.html": [
            "BAI_13B_6_V1_1_SAFE_SCOPE_SUBMIT",
        ],
        "app/templates/partials/dropdown_menu_v1.html": [
            "BAI_13B_5_V1_TEAM_MENU_START",
            "BAI_13B_5_V1_CSVC_MENU_START",
            "/bieu-nhap/th-01-gv",
            "/bieu-nhap/thcs-01-csvc",
        ],
    }
    for rel, markers in required.items():
        text = _read_text(rel)
        for marker in markers:
            if marker not in text:
                raise RuntimeError(
                    f"Chưa đúng nền Bài 13B-6 V1.1: {rel} thiếu {marker}. "
                    "Dừng cài để không ảnh hưởng mã nguồn."
                )


def _backup_files() -> list[dict]:
    BACKUP.mkdir(parents=True, exist_ok=False)
    manifest: list[dict] = []
    for rel in FILES_TO_BACKUP:
        src = PROJECT / rel
        existed = src.exists()
        manifest.append({"path": rel, "existed": existed})
        if existed:
            dst = BACKUP / rel
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, dst)
    MANIFEST.write_text(
        json.dumps(manifest, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    return manifest


def _restore(manifest: list[dict]) -> None:
    for item in reversed(manifest):
        target = PROJECT / item["path"]
        if item["existed"]:
            src = BACKUP / item["path"]
            if src.exists():
                target.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(src, target)
        elif target.exists() and target.is_file():
            target.unlink()


def _write_payload() -> None:
    for rel, encoded in PAYLOAD.items():
        target = PROJECT / rel
        target.parent.mkdir(parents=True, exist_ok=True)
        raw = gzip.decompress(base64.b64decode(encoded.encode("ascii")))
        target.write_bytes(raw)


def _compile_and_check_templates() -> None:
    for rel in [
        "app/report_input_models.py",
        "app/routers/report_inputs.py",
        "app/pcgd_xmc_report_builders_v1.py",
    ]:
        subprocess.run(
            [sys.executable, "-m", "py_compile", str(PROJECT / rel)],
            cwd=PROJECT,
            check=True,
        )

    from jinja2 import Environment, FileSystemLoader
    env = Environment(loader=FileSystemLoader(str(APP / "templates")))
    for name in [
        "report_inputs/structured_school_form.html",
        "partials/dropdown_menu_v1.html",
        "report_inputs/gv_mn01.html",
        "report_inputs/csvc_mn01.html",
    ]:
        env.get_template(name)


def _norm(value: str | None) -> str:
    text = " ".join(str(value or "").strip().split()).upper()
    text = unicodedata.normalize("NFD", text)
    text = "".join(ch for ch in text if unicodedata.category(ch) != "Mn")
    return " ".join(text.split())


def _commune_base(value: str | None) -> str:
    text = _norm(value)
    for prefix in ("PHUONG ", "XA ", "THI TRAN "):
        if text.startswith(prefix):
            return text[len(prefix):].strip()
    return text


def _clean_school_name(value: str | None) -> str:
    text = " ".join(str(value or "").strip().split())
    return text.replace("amp;", "&")


def _create_tables_and_import() -> dict:
    # Import sau khi đã ghi model mới.
    from sqlalchemy import select
    from app.database import Base, SessionLocal, engine
    from app.models import Commune, School, SchoolYear
    from app.report_input_models import SchoolNetworkYearData

    Base.metadata.create_all(bind=engine)

    raw = gzip.decompress(base64.b64decode(NETWORK_DATA_B64.encode("ascii")))
    dataset = json.loads(raw.decode("utf-8"))
    records = list(dataset.get("records") or [])
    source_year_code = str(dataset.get("source_year") or "2025-2026")

    stats = {
        "records_total": len(records),
        "records_imported": 0,
        "records_skipped_no_commune": 0,
        "records_skipped_unmatched_commune": 0,
        "schools_created": 0,
        "schools_existing": 0,
        "schools_moved_commune": 0,
        "network_created": 0,
        "network_updated": 0,
        "unmatched_communes": set(),
        "province_school_skipped": [],
    }

    db = SessionLocal()
    try:
        year = db.scalar(select(SchoolYear).where(SchoolYear.code == source_year_code))
        if year is None:
            year = SchoolYear(
                code=source_year_code,
                name=f"Năm học {source_year_code}",
                is_active=True,
            )
            db.add(year)
            db.flush()

        communes = list(db.scalars(select(Commune).where(Commune.is_active.is_(True))).all())
        full_map = {}
        base_map = {}
        for commune in communes:
            full_map.setdefault(_norm(commune.name), []).append(commune)
            base_map.setdefault(_commune_base(commune.name), []).append(commune)

        existing_schools = {
            str(s.code).strip(): s
            for s in db.scalars(select(School)).all()
        }

        def find_commune(name: str):
            if not name:
                return None
            full = full_map.get(_norm(name), [])
            if len(full) == 1:
                return full[0]
            base = base_map.get(_commune_base(name), [])
            if len(base) == 1:
                return base[0]
            return None

        for rec in records:
            code = str(rec.get("school_code") or "").strip()
            source_name = _clean_school_name(rec.get("school_name"))
            commune_name = str(rec.get("commune_name") or "").strip()
            level = str(rec.get("level") or "").strip().upper()
            data = rec.get("data") or {}

            if not code or level not in {"TH", "THCS"}:
                continue

            school = existing_schools.get(code)
            commune = find_commune(commune_name) if commune_name else None

            if school is None:
                if commune is None:
                    if commune_name:
                        stats["records_skipped_unmatched_commune"] += 1
                        stats["unmatched_communes"].add(commune_name)
                    else:
                        stats["records_skipped_no_commune"] += 1
                        if len(stats["province_school_skipped"]) < 30:
                            stats["province_school_skipped"].append(f"{code} - {source_name}")
                    continue

                school = School(
                    commune_id=int(commune.id),
                    code=code,
                    name=source_name or code,
                    is_active=True,
                )
                db.add(school)
                db.flush()
                existing_schools[code] = school
                stats["schools_created"] += 1
            else:
                stats["schools_existing"] += 1
                if commune is not None and int(school.commune_id) != int(commune.id):
                    # Mã trường trong nguồn là khóa nhận diện đáng tin cậy;
                    # cập nhật xã để trường xuất hiện đúng danh sách chọn.
                    school.commune_id = int(commune.id)
                    stats["schools_moved_commune"] += 1
                if not str(school.name or "").strip() and source_name:
                    school.name = source_name
                school.is_active = True

            network = db.scalar(
                select(SchoolNetworkYearData).where(
                    SchoolNetworkYearData.school_id == int(school.id),
                    SchoolNetworkYearData.school_year_id == int(year.id),
                    SchoolNetworkYearData.level_code == level,
                )
            )
            source_file = (
                "Thong_ke_mang_luoi_lop_HS_GV_TH.xlsx"
                if level == "TH"
                else "Thong_ke_mang_luoi_lop_HS_GV_THCS.xlsx"
            )
            if network is None:
                network = SchoolNetworkYearData(
                    school_id=int(school.id),
                    school_year_id=int(year.id),
                    level_code=level,
                )
                db.add(network)
                stats["network_created"] += 1
            else:
                stats["network_updated"] += 1

            network.data_json = json.dumps(data, ensure_ascii=False, separators=(",", ":"))
            network.source_name = source_file
            stats["records_imported"] += 1

        db.commit()

        # Xác nhận số bản ghi thực tế sau import.
        stats["network_th"] = len(list(db.scalars(
            select(SchoolNetworkYearData).where(SchoolNetworkYearData.level_code == "TH")
        ).all()))
        stats["network_thcs"] = len(list(db.scalars(
            select(SchoolNetworkYearData).where(SchoolNetworkYearData.level_code == "THCS")
        ).all()))
        stats["schools_total"] = len(list(db.scalars(select(School)).all()))
        stats["unmatched_communes"] = sorted(stats["unmatched_communes"])
        return stats
    finally:
        db.close()


def _verify_new_source() -> None:
    checks = {
        "app/report_input_models.py": [
            "class SchoolNetworkYearData",
            "school_network_year_data",
        ],
        "app/routers/report_inputs.py": [
            "BAI_13B_6_V1_2_NETWORK_DATA_START",
            "_structured_network_school_ids",
            "network_reference_year",
        ],
        "app/pcgd_xmc_report_builders_v1.py": [
            "BAI_13B_6_V1_2_NETWORK_EXPORT_START",
            "_school_supports_report_level",
        ],
        "app/templates/report_inputs/structured_school_form.html": [
            "Dữ liệu mạng lưới",
            "Số lớp tham chiếu",
        ],
    }
    for rel, markers in checks.items():
        text = _read_text(rel)
        for marker in markers:
            if marker not in text:
                raise RuntimeError(f"Kiểm tra sau cài không đạt: {rel} / {marker}")


def _clear_cache() -> None:
    for cache in APP.rglob("__pycache__"):
        if cache.is_dir():
            shutil.rmtree(cache, ignore_errors=True)


